def set(self, key: Key, flag: int, *, recursive: bool) -> None:  # noqa: A003
    cont = self._flags
    key_parent, key_stem = key[:-1], key[-1]
    for k in key_parent:
        if k not in cont:
            cont[k] = {"flags": set(), "recursive_flags": set(), "nested": {}}
